# Generated by build.py from recipe.yml for recipe http-time-out-a-hanging-server. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'once' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/other.txt'), "not held`n")
[IO.File]::WriteAllText((Join-Path $PWD 'once/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"delay;ms=5000;stage=command;path=/hello.txt"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -m 2 http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
